package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.JdbcFrozenInputs;
import com.lianxibu.site.service.jobs.GenerationFlowService.*;
import com.lianxibu.site.service.jobs.ReportInputSnapshotService.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.json.JsonMapper;

/** All count, source and SourceProof facts here are explicitly fictional pure mapper inputs. */
class EntityHeatReportCandidateTest {
    final Instant cutoff=Instant.parse("2026-01-02T21:00:00Z");final LocalDate day=LocalDate.of(2026,1,2);
    EntityHeatCutoffProofService.Count count(String id,long total){return new EntityHeatCutoffProofService.Count(new EntityHeatSnapshot(id,"news_tech",3,total,"Fictional count display",null,cutoff.minusSeconds(100),day,false),"a".repeat(64),"b".repeat(64),cutoff.minusSeconds(1));}
    NewsSourceReportComponentService.EntityLeaf leaf(String id,boolean valid,boolean blocked){var payload=JsonMapper.shared().createObjectNode().put("title","Fictional original title").put("source_summary","Fictional original summary").put("body_text","Fictional full source body ".repeat(100));return new NewsSourceReportComponentService.EntityLeaf("fictional-item-"+id,id,"fictional-source","fictional-run","fictional-stable-"+id,day,"fictional-value-root-"+id,"c".repeat(64),2,CanonicalJson.hash(CanonicalJson.Domain.CONTENT,payload),JdbcFrozenInputs.canonical(payload),"Fictional original title","Fictional original summary","{\"kind\":\"article_revision\",\"id\":\"fictional-revision-"+id+"\"}",0,valid,blocked,cutoff.minusSeconds(2));}
    Candidate daily(){String body="{\"summary\":\"Fictional daily input\"}",hash=CanonicalJson.hash(CanonicalJson.Domain.CONTENT,CanonicalJson.parse(body));return new Candidate(Group.SOURCE_SUMMARIES,new Metadata(new ResourceRef("source_run","fictional-daily-run",null),1L,"fictional-daily-version",hash,"fictional-daily-source","fictional-daily-run",null,day,null,"Fictional daily input",null),new Evidence("fictional-daily-evidence","source_summary",day,cutoff.minusSeconds(1),hash,body,true,false,"accepted",List.of()),"news_tech",false,false,null,null);}
    ReportInputSnapshotService.FrozenInput freeze(List<EntityHeatReportCandidate.Value> values,boolean withDaily){var candidates=new ArrayList<Candidate>();if(withDaily)candidates.add(daily());values.forEach(v->candidates.add(v.candidate()));var dependencies=values.stream().map(v->v.dependency().id()).distinct().toList();var command=new Prepare("fictional-heat-daily",1,Stage.DAILY_REPORT,day,null,List.of(),List.of(),List.of(),false,"d".repeat(64));return new ReportInputSnapshotService((c,t)->new SourceProof(t,day,day.plusDays(1),true,candidates,List.of(),List.of(),dependencies)).freeze(command,cutoff);}
    @Test void FullOriginalBodyAndCutoffSnapshotHaveStableIdentityAndNativeReferenceFacts(){var leaf=leaf("fictional-entity",true,false);var value=EntityHeatReportCandidate.create(count(leaf.entityId(),7),leaf,cutoff,true);var candidate=value.candidate();var body=CanonicalJson.parse(candidate.evidence().bodyJson());assertEquals(CanonicalJson.parse(leaf.bodyJson()),body.get("source_member").get("body"));assertTrue(body.get("source_member").get("body").get("body_text").asText().length()>800);assertEquals(7,candidate.metadata().occurrenceCount());assertEquals("Fictional original title",candidate.metadata().title());assertEquals(cutoff,candidate.countCutoff());assertEquals("article_revision",CanonicalJson.parse(value.referenceJson()).get("kind").asText());assertEquals(List.of(leaf.rootId()),candidate.evidence().references());assertEquals(count(leaf.entityId(),7).availableAt(),candidate.evidence().completedAt());assertEquals(value,EntityHeatReportCandidate.create(count(leaf.entityId(),7),leaf,cutoff,true));assertFalse(value.toString().contains("fictional"));assertThrows(UnsupportedOperationException.class,()->candidate.evidence().references().clear());}
    @Test void RankingUsesEveryQualifiedCandidateAndRecomputesAfterNativeBodyExclusion(){var values=new ArrayList<EntityHeatReportCandidate.Value>();for(int i=0;i<7;i++){String id="fictional-entity-"+i;values.add(EntityHeatReportCandidate.create(count(id,i==6?99:8),leaf(id,i!=6,false),cutoff,true));}var frozen=freeze(values,true);var profile=CanonicalJson.parse(frozen.snapshotJson()).get(com.lianxibu.site.service.content.ReportInputProfile.FIELD);var included=profile.get("members").valueStream().filter(n->n.get("group").asText().equals("historical_heat")&&n.get("included").booleanValue()).toList();assertEquals(5,included.size());assertEquals(Set.of("fictional-entity-0","fictional-entity-1","fictional-entity-2","fictional-entity-3","fictional-entity-4"),included.stream().map(n->n.get("resource_ref").get("id").asText()).collect(java.util.stream.Collectors.toSet()));assertEquals(8,profile.get("total").intValue());assertTrue(frozen.hasContent());}
    @Test void CurrentAssociationInvalidityAndHeatOnlyInputCannotBorrowUnqualifiedBody(){for(var flags:List.of(new boolean[]{false,false,true},new boolean[]{true,true,true},new boolean[]{true,false,false})){var value=EntityHeatReportCandidate.create(count("fictional-entity",7),leaf("fictional-entity",flags[0],flags[1]),cutoff,flags[2]);var frozen=freeze(List.of(value),true);assertEquals(1,CanonicalJson.parse(frozen.snapshotJson()).get("members").size());}var valid=EntityHeatReportCandidate.create(count("fictional-entity",7),leaf("fictional-entity",true,false),cutoff,true);assertFalse(freeze(List.of(valid),false).hasContent());}
    @Test void WrongEntityUnknownCountDamagedOriginalBodyAndLateFactsRejectPureMapping(){var original=leaf("fictional-entity",true,false);assertThrows(RuntimeException.class,()->EntityHeatReportCandidate.create(count("fictional-alien",7),original,cutoff,true));assertThrows(RuntimeException.class,()->EntityHeatReportCandidate.create(count("fictional-entity",7),original,cutoff.plusSeconds(1),true));assertThrows(RuntimeException.class,()->EntityHeatReportCandidate.create(count("fictional-entity",7),original,cutoff.minusSeconds(3),true));var unknown=new EntityHeatCutoffProofService.Count(new EntityHeatSnapshot("fictional-entity","news_tech",3,null,null,null,null,null,true),"a".repeat(64),"b".repeat(64),cutoff);assertThrows(RuntimeException.class,()->EntityHeatReportCandidate.create(unknown,original,cutoff,true));var bad=new NewsSourceReportComponentService.EntityLeaf(original.itemId(),original.entityId(),original.sourceId(),original.runId(),original.sourceItemId(),original.day(),original.rootId(),original.inputHash(),original.inputRevision(),"f".repeat(64),original.bodyJson(),original.title(),original.summary(),original.referenceJson(),original.validityRevision(),true,false,original.availableAt());assertThrows(RuntimeException.class,()->EntityHeatReportCandidate.create(count("fictional-entity",7),bad,cutoff,true));}
}
